from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]
names=[('MARKTGRUEN','Neighbourhood supermarket',['Produce, dry goods, chilled cabinets, bakery island, checkouts, accessible WC, receiving','Stockroom, purchasing office, staff kitchen, lockers, WC','Separate-entry two-bedroom loft home']),('KRUME & KORN','Bakery',['Bread counter, pastry displays, baking/prep kitchen, wash-up, WC','Bakers maisonette: living/kitchen, two bedrooms, bathroom, storage']),('KESSEL & KAKAO','Cafe',['Coffee bar, pastry display, varied seating, prep kitchen, customer WC','Quiet reading cafe: lounge, tea pantry, games room, WC']),('FABELHAUS','Bookshop',['Bookshelves, accessible browse aisles, central display tables, till, stock, WC','Illustrator home/studio: bedroom, drawing studio, kitchen/living, bathroom']),('TANNENGRUEN','Florist',['Bouquet workbench, pot/display shelves, cold store, till, WC','Conservatory home: planted dining room, bedroom, kitchen, bathroom']),('FADENWERK','Clothing and knitwear',['Garment rails, knit displays, fitting rooms, till, stock, WC','Tailoring atelier: sewing, cutting, fabric store, office, WC']),('HAUS ABENDROT','Boutique hotel',['Reception, luggage store, breakfast lounge, kitchen, public WC','Two separately furnished guest suites with ensuite bathrooms and linen cupboard','Two different attic suites with ensuite bathrooms, reading alcoves']),('LICHTSPIEL','Toy shop',['Toy shelving, play-test table, display train, checkout, stock, WC','Family home: living/kitchen, parents room, child room, bathroom']),('GOLDFADEN','Jewellery and craft',['Glazed displays, consultation counter, jeweller bench, secure stock, WC','Maker loft: workshop, living/kitchen, bedroom, bathroom']),('STERNBLICK','Pharmacy',['Customer display shelving, dispensary counter, consultation room, stock, WC','Practice rooms: reception, two distinct consultation rooms, staff pantry, WC']),('NORDRAD','Cycle shop',['Cycle display, service workstands, tools, parts, till, WC','Cyclist home: mudroom, living/kitchen, bedroom, bathroom, gear store']),('WINTERPOST','Stationery and parcel shop',['Stationery shelving, cards/gifts, parcel lockers, service counter, sorting, WC','Writers home: library/living, separate kitchen, study, bedroom, bathroom'])]
